use std::time::Duration;

use bytes::Bytes;
use serde_json::json;
use sprig_ai::embedding::store::{EmbeddedColumn, NewColumn, Pending, State, Store};
use sprig_ai::embedding::{self, ModelRef, failed};
use sprig_catalog::ddl::{database_key, object_key};
use sprig_catalog::pool_wait::Bounded as _;
use sprig_catalog::store::{Namespace, ObjectKind, ObjectState};
use sprig_catalog::{CatalogLocator as _, TenantCatalog};
use sprig_common::{Result, SprigCode, SprigError};
use sprig_feed::subs::{Subscription, Subscriptions};
use sprig_feed::{ResumeToken, StartAt, TailOptions, TenantTail};
use sprig_proto_mysql::StatusFlags;
use sprig_proto_mysql::packets::OkPacket;
use sprig_sql::embedcol::{self, Clause, Meta, Mode, Spec, Stmt, Touch, quote};

use super::PassSession;
use super::tenant::Step;
use crate::pipeline::{ExecCtx, ResultSink, Wire};
use crate::tenant::TenantServices;

mod engine;
pub(crate) mod runner;
pub(crate) mod write;

/// The feed subscription kind (and the controller's job kind).
pub(crate) const KIND: &str = "ai_embed";

/// The subscription of embedded column `id`.
#[must_use]
pub(crate) fn sub_name(id: u64) -> String {
    format!("emb:e{id}")
}

fn no_db() -> SprigError {
    SprigError::standard(1046, *b"3D000", "No database selected")
}

/// What the hook does with a statement.
enum Plan {
    /// Not ours.
    Pass,
    /// Embedding clauses to add (`CREATE TABLE`, `ALTER TABLE ... ADD`).
    Declare {
        db: String,
        table: String,
        create: bool,
        clauses: Vec<Clause>,
    },
    /// A new generation for an embedded column.
    Modify {
        db: String,
        table: String,
        clause: Clause,
    },
    /// An `ALTER TABLE` touching columns of a table, maybe embedded ones.
    Touches {
        db: String,
        table: String,
        specs: Vec<(Touch, String, std::ops::Range<usize>)>,
    },
}

impl Plan {
    /// The database the statement acts in.
    fn db(&self) -> Option<&str> {
        match self {
            Plan::Pass => None,
            Plan::Declare { db, .. } | Plan::Modify { db, .. } | Plan::Touches { db, .. } => {
                Some(db)
            }
        }
    }
}

impl PassSession {
    /// Embedded-column DDL: `None` when the statement isn't one (see the
    /// module docs).
    #[allow(clippy::too_many_lines)] // engine tables, then MariaDB's, step by step
    pub(super) async fn tenant_embed_ddl(
        &mut self,
        cx: &mut ExecCtx<'_>,
        text: &Bytes,
        more: bool,
        out: &mut dyn ResultSink,
    ) -> Result<Option<Step>> {
        // The hook's own statements come back through the tenant path.
        if self.tenant.as_deref().is_none_or(|ts| ts.types.internal) {
            return Ok(None);
        }
        let first = text
            .iter()
            .position(|b| !b.is_ascii_whitespace())
            .map_or(&text[..0], |i| &text[i..]);
        if !(first.len() >= 6
            && (first[..6].eq_ignore_ascii_case(b"CREATE")
                || first[..5].eq_ignore_ascii_case(b"ALTER")))
        {
            return Ok(None);
        }
        // `CREATE TABLE b LIKE a` of an engine table with embedded columns:
        // the copy gets records of its own (embed_ddl::engine).
        if let Some(like) = std::str::from_utf8(text).ok().and_then(engine::parse_like) {
            let wire = out.wire();
            return match Box::pin(self.engine_like(cx, wire, text, &like)).await {
                Ok(false) => Ok(None),
                Ok(true) => {
                    let mut status = self.status();
                    if more {
                        status |= StatusFlags::MORE_RESULTS_EXISTS;
                    }
                    out.ok(OkPacket::new(status)).await?;
                    Ok(Some(Step {
                        errored: false,
                        status: Some(status),
                    }))
                }
                Err(e) => Ok(Some(self.fail(out, &e).await?)),
            };
        }
        let (lex, _) = self.lex_opts();
        let plan = match embedcol::parse(text, &lex) {
            Ok(None) => return Ok(None),
            Ok(Some(stmt)) => self.plan(stmt),
            Err(msg) => return Ok(Some(self.fail(out, &failed(msg)).await?)),
        };
        let plan = match plan {
            Ok(p) => p,
            Err(e) => return Ok(Some(self.fail(out, &e).await?)),
        };
        let Ok(sql) = std::str::from_utf8(text) else {
            return Ok(None);
        };
        let wire = out.wire();
        // Engine tables: their own layout, records and runner.
        if let Some(db) = plan.db() {
            let (cat, lctn) = match self.embed_cat().await {
                Ok(x) => x,
                Err(e) => return Ok(Some(self.fail(out, &e).await?)),
            };
            if engine::is_engine_db(&cat, db, lctn) {
                let r = match &plan {
                    Plan::Pass => return Ok(None),
                    Plan::Declare {
                        db,
                        table,
                        create,
                        clauses,
                    } => {
                        if embedcol::names_reserved(text, &lex) {
                            let e = SprigError::new(
                                SprigCode::ReservedName,
                                "a statement declaring an embedded column can't name a reserved (_sprig_) column",
                            );
                            return Ok(Some(self.fail(out, &e).await?));
                        }
                        let (db, table, create, clauses) =
                            (db.clone(), table.clone(), *create, clauses.clone());
                        Box::pin(self.engine_declare(cx, wire, sql, &db, &table, create, &clauses))
                            .await
                    }
                    Plan::Modify { db, table, clause } => {
                        let def = engine::table_def(&cat, db, table, lctn);
                        let known = match &def {
                            Some(d) => self.engine_embedded_of(d.object.0).await?,
                            None => Vec::new(),
                        };
                        if known
                            .iter()
                            .any(|e| e.column.eq_ignore_ascii_case(&clause.column))
                        {
                            Err(engine::modify_refused(&clause.column))
                        } else {
                            Err(failed(format!(
                                "{} isn't an embedded column; add one with ADD COLUMN ... GENERATED BY EMBEDDING",
                                clause.column
                            )))
                        }
                    }
                    Plan::Touches { db, table, specs } => {
                        let Some(def) = engine::table_def(&cat, db, table, lctn) else {
                            return Ok(None);
                        };
                        let specs = specs.clone();
                        match Box::pin(self.engine_touches(cx, wire, sql, &def, &specs)).await {
                            Ok(true) => Ok(()),
                            Ok(false) => return Ok(None),
                            Err(e) => Err(e),
                        }
                    }
                };
                if let Err(e) = r {
                    return Ok(Some(self.fail(out, &e).await?));
                }
                let mut status = self.status();
                if more {
                    status |= StatusFlags::MORE_RESULTS_EXISTS;
                }
                out.ok(OkPacket::new(status)).await?;
                return Ok(Some(Step {
                    errored: false,
                    status: Some(status),
                }));
            }
        }
        let r = match plan {
            Plan::Pass => return Ok(None),
            Plan::Declare {
                db,
                table,
                create,
                clauses,
            } => {
                if embedcol::names_reserved(text, &lex) {
                    let e = SprigError::new(
                        SprigCode::ReservedName,
                        "a statement declaring an embedded column can't name a reserved (_sprig_) column",
                    );
                    return Ok(Some(self.fail(out, &e).await?));
                }
                Box::pin(self.declare(cx, wire, sql, &db, &table, create, &clauses)).await
            }
            Plan::Modify { db, table, clause } => {
                Box::pin(self.modify(cx, wire, &db, &table, &clause)).await
            }
            Plan::Touches { db, table, specs } => {
                match Box::pin(self.touches(cx, wire, sql, &db, &table, &specs)).await {
                    Ok(true) => Ok(()),
                    Ok(false) => return Ok(None),
                    Err(e) => Err(e),
                }
            }
        };
        if let Err(e) = r {
            return Ok(Some(self.fail(out, &e).await?));
        }
        let mut status = self.status();
        if more {
            status |= StatusFlags::MORE_RESULTS_EXISTS;
        }
        out.ok(OkPacket::new(status)).await?;
        Ok(Some(Step {
            errored: false,
            status: Some(status),
        }))
    }

    fn plan(&self, stmt: Stmt) -> Result<Plan> {
        let current = self.current_logical();
        let pick = |db: Option<String>| db.or_else(|| current.clone()).ok_or_else(no_db);
        Ok(match stmt {
            Stmt::CreateTable { db, table, clauses } => {
                if clauses.is_empty() {
                    return Ok(Plan::Pass);
                }
                Plan::Declare {
                    db: pick(db)?,
                    table,
                    create: true,
                    clauses,
                }
            }
            Stmt::AlterTable { db, table, specs } => {
                let db = pick(db)?;
                let adds: Vec<Clause> = specs
                    .iter()
                    .filter_map(|s| match s {
                        Spec::Add(c) => Some(c.clone()),
                        _ => None,
                    })
                    .collect();
                let modifies: Vec<&Clause> = specs
                    .iter()
                    .filter_map(|s| match s {
                        Spec::Modify(c) => Some(c),
                        _ => None,
                    })
                    .collect();
                if let Some(c) = modifies.first() {
                    if specs.len() > 1 || !adds.is_empty() {
                        return Err(failed(
                            "MODIFY COLUMN ... GENERATED BY EMBEDDING must be the statement's only change",
                        ));
                    }
                    return Ok(Plan::Modify {
                        db,
                        table,
                        clause: (*c).clone(),
                    });
                }
                if !adds.is_empty() {
                    return Ok(Plan::Declare {
                        db,
                        table,
                        create: false,
                        clauses: adds,
                    });
                }
                Plan::Touches {
                    db,
                    table,
                    specs: specs
                        .into_iter()
                        .filter_map(|s| match s {
                            Spec::Touch { kind, column, span } => Some((kind, column, span)),
                            _ => None,
                        })
                        .collect(),
                }
            }
        })
    }

    fn services_and_tenant(
        &self,
    ) -> Result<(Arc<TenantServices>, sprig_common::ids::TenantId, u32)> {
        let ts = self
            .tenant
            .as_deref()
            .ok_or_else(|| SprigError::internal("no tenant"))?;
        Ok((
            Arc::clone(ts.services()),
            ts.tenant,
            ts.principal.user_id.map_or(0, |u| u.0),
        ))
    }

    /// The table's object id and database id.
    async fn table_object(&mut self, db: &str, table: &str) -> Result<Option<(u32, u64)>> {
        let ts = self
            .tenant
            .as_deref_mut()
            .ok_or_else(|| SprigError::internal("no tenant"))?;
        let lctn = ts.lower_case_table_names();
        let cat = ts.refresh().await?;
        Ok(table_in(&cat, db, table, lctn))
    }

    /// Runs `sql` through the session with the hidden names allowed.
    async fn embed_run(&mut self, cx: &mut ExecCtx<'_>, wire: Wire, sql: &str) -> Result<()> {
        if let Some(ts) = self.tenant.as_deref_mut() {
            ts.types.internal = true;
        }
        let r = self.sub_rows(cx, wire, sql).await;
        if let Some(ts) = self.tenant.as_deref_mut() {
            ts.types.internal = false;
        }
        r.map(|_| ())
    }

    /// Whether `db`.`table` has a primary key the feed carries.
    async fn has_primary_key(
        &mut self,
        cx: &mut ExecCtx<'_>,
        wire: Wire,
        db: &str,
        table: &str,
    ) -> Result<bool> {
        let lit = |s: &str| format!("'{}'", s.replace('\\', "\\\\").replace('\'', "''"));
        let rows = self
            .sub_rows(
                cx,
                wire,
                &format!(
                    "SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = {} \
                     AND TABLE_NAME = {} AND INDEX_NAME = 'PRIMARY'",
                    lit(db),
                    lit(table)
                ),
            )
            .await?;
        Ok(rows
            .first()
            .and_then(|r| r.first())
            .and_then(|v| v.as_deref())
            .and_then(|v| std::str::from_utf8(v).ok()?.parse::<u64>().ok())
            .unwrap_or(0)
            > 0)
    }

    /// The model a clause names, checked.
    fn model_for(svc: &TenantServices, cat: &TenantCatalog, c: &Clause) -> Result<ModelRef> {
        embedcol::check_column_name(&c.column).map_err(failed)?;
        if c.mode == Mode::Sync {
            return Err(failed(format!(
                "embedded column {}: ON CHANGE SYNC isn't available yet; declare it ASYNC (the default)",
                c.column
            )));
        }
        let models = svc.settings.get(
            &embedding::MODELS,
            &cat.setting_ctx(&svc.dc),
            Some(&cat.settings),
        );
        let m = embedding::resolve(&c.model, &models)?;
        if !m.is_local() {
            return Err(failed(format!(
                "embedded column {}: '{}' is a provider's model; embedded columns use local models for now ({})",
                c.column,
                c.model,
                embedding::LOCAL_ALIAS
            )));
        }
        if m.dimensions != c.dim {
            return Err(failed(format!(
                "embedded column {}: model '{}' gives {} dimensions, not {}; declare VECTOR({})",
                c.column, c.model, m.dimensions, c.dim, m.dimensions
            )));
        }
        if let Some(n) = c.max_input_tokens
            && m.is_local()
            && n > u32::try_from(sprig_embed::MAX_TOKENS).unwrap_or(u32::MAX)
        {
            return Err(failed(format!(
                "embedded column {}: model '{}' reads at most {} tokens",
                c.column,
                c.model,
                sprig_embed::MAX_TOKENS
            )));
        }
        Ok(m)
    }

    #[allow(clippy::too_many_arguments)] // the statement and its parts
    async fn declare(
        &mut self,
        cx: &mut ExecCtx<'_>,
        wire: Wire,
        sql: &str,
        db: &str,
        table: &str,
        create: bool,
        clauses: &[Clause],
    ) -> Result<()> {
        let (svc, tenant, user) = self.services_and_tenant()?;
        let cat = {
            let ts = self
                .tenant
                .as_deref_mut()
                .ok_or_else(|| SprigError::internal("no tenant"))?;
            ts.refresh().await?
        };
        let mut models = Vec::with_capacity(clauses.len());
        for c in clauses {
            models.push(Self::model_for(&svc, &cat, c)?);
        }
        if create {
            let upper = sql.to_ascii_uppercase();
            if !upper.contains("PRIMARY KEY") {
                return Err(failed(format!(
                    "{table}: a table with embedded columns needs a primary key"
                )));
            }
        } else if self.table_object(db, table).await?.is_some()
            && !self.has_primary_key(cx, wire, db, table).await?
        {
            return Err(failed(format!(
                "{table}: a table with embedded columns needs a primary key"
            )));
        }
        let edits: Vec<(std::ops::Range<usize>, String)> = clauses
            .iter()
            .map(|c| {
                let meta = Meta {
                    column: c.column.clone(),
                    model: c.model.clone(),
                    generation: 1,
                    mode: c.mode,
                    max_input_tokens: c.max_input_tokens,
                    shadow: false,
                };
                let defs = embedcol::column_defs(&c.column, c.dim, &c.source, &meta, None, true);
                let text = if create {
                    defs.join(", ")
                } else {
                    defs.iter()
                        .map(|d| format!("ADD COLUMN {d}"))
                        .collect::<Vec<_>>()
                        .join(", ")
                };
                (c.span.clone(), text)
            })
            .collect();
        let rewritten = embedcol::splice(sql, edits);
        self.embed_run(cx, wire, &rewritten).await?;
        // The table (new or altered) and its rows.
        let Some((db_id, object)) = self.table_object(db, table).await? else {
            return Err(SprigError::internal(format!(
                "{db}.{table} isn't in the catalog after its DDL"
            )));
        };
        let ep = svc.locator.writer(tenant).await?;
        let mut conn = ep.pool.get_conn_bounded().await.map_err(|e| {
            SprigError::new(SprigCode::CatalogUnavailable, "catalog unreachable").with_source(e)
        })?;
        let store = Store::new(ep.store.schema());
        for (c, m) in clauses.iter().zip(models) {
            let id = store
                .insert(
                    &mut conn,
                    &NewColumn {
                        db_id,
                        object_id: object,
                        column: c.column.clone(),
                        source: c.source.clone(),
                        model: m,
                        mode: c.mode.as_str().to_owned(),
                        max_input_tokens: c.max_input_tokens,
                        created_by: Some(user),
                    },
                )
                .await?;
            register(&svc, tenant, id, db, table, object, &c.column).await?;
            tracing::info!(%tenant, %db, %table, column = %c.column, embedding = id, model = %c.model, "embedded column declared");
        }
        Ok(())
    }

    async fn embedded_of(&self, object: u64) -> Result<Vec<EmbeddedColumn>> {
        let (svc, tenant, _) = self.services_and_tenant()?;
        let ep = svc.locator.writer(tenant).await?;
        // A records-only catalog (no MariaDB schema) keeps no embedded columns.
        if sprig_catalog::migrate::records_catalog(ep.store.schema()).await? {
            return Ok(Vec::new());
        }
        let mut conn = ep.pool.get_conn_bounded().await.map_err(|e| {
            SprigError::new(SprigCode::CatalogUnavailable, "catalog unreachable").with_source(e)
        })?;
        Store::new(ep.store.schema())
            .of_object(&mut conn, object)
            .await
    }

    async fn modify(
        &mut self,
        cx: &mut ExecCtx<'_>,
        wire: Wire,
        db: &str,
        table: &str,
        c: &Clause,
    ) -> Result<()> {
        let (svc, tenant, _) = self.services_and_tenant()?;
        let Some((_, object)) = self.table_object(db, table).await? else {
            return Err(SprigError::standard(
                1146,
                *b"42S02",
                format!("Table '{db}.{table}' doesn't exist"),
            ));
        };
        let Some(e) = self
            .embedded_of(object)
            .await?
            .into_iter()
            .find(|e| e.column.eq_ignore_ascii_case(&c.column))
        else {
            return Err(failed(format!(
                "{} isn't an embedded column; add one with ADD COLUMN ... GENERATED BY EMBEDDING",
                c.column
            )));
        };
        let cat = {
            let ts = self
                .tenant
                .as_deref_mut()
                .ok_or_else(|| SprigError::internal("no tenant"))?;
            ts.refresh().await?
        };
        let m = Self::model_for(&svc, &cat, c)?;
        if e.state == State::Reembedding {
            return Err(failed(format!(
                "embedded column {} is being re-embedded (generation {}); wait until it is ready",
                e.column,
                e.generation + 1
            )));
        }
        let new_source = c.source.trim() != e.source.trim();
        if !new_source && m == e.model && c.max_input_tokens == e.max_input_tokens {
            // The same declaration: nothing to do.
            return Ok(());
        }
        let generation = e.generation + 1;
        let meta = Meta {
            column: e.column.clone(),
            model: c.model.clone(),
            generation,
            mode: c.mode,
            max_input_tokens: c.max_input_tokens,
            shadow: true,
        };
        let defs = embedcol::column_defs(
            &e.column,
            c.dim,
            &c.source,
            &meta,
            Some(generation),
            new_source,
        );
        let sql = format!(
            "ALTER TABLE {}.{} {}",
            quote(db),
            quote(table),
            defs.iter()
                .map(|d| format!("ADD COLUMN {d}"))
                .collect::<Vec<_>>()
                .join(", ")
        );
        self.embed_run(cx, wire, &sql).await?;
        let ep = svc.locator.writer(tenant).await?;
        let mut conn = ep.pool.get_conn_bounded().await.map_err(|e| {
            SprigError::new(SprigCode::CatalogUnavailable, "catalog unreachable").with_source(e)
        })?;
        Store::new(ep.store.schema())
            .start_reembedding(
                &mut conn,
                e.id,
                &Pending {
                    generation,
                    source: c.source.clone(),
                    new_source,
                    model: m,
                    max_input_tokens: c.max_input_tokens,
                },
            )
            .await?;
        tracing::info!(%tenant, %db, %table, column = %e.column, generation, model = %c.model, "embedded column re-embedding started");
        Ok(())
    }

    /// An `ALTER TABLE` touching columns: `false` when none is embedded
    /// (the statement runs as usual).
    async fn touches(
        &mut self,
        cx: &mut ExecCtx<'_>,
        wire: Wire,
        sql: &str,
        db: &str,
        table: &str,
        specs: &[(Touch, String, std::ops::Range<usize>)],
    ) -> Result<bool> {
        let Some((_, object)) = self.table_object(db, table).await? else {
            return Ok(false);
        };
        let embedded = self.embedded_of(object).await?;
        if embedded.is_empty() {
            return Ok(false);
        }
        let find = |c: &str| embedded.iter().find(|e| e.column.eq_ignore_ascii_case(c));
        let mut edits = Vec::new();
        let mut dropped = Vec::new();
        for (kind, column, span) in specs {
            let Some(e) = find(column) else {
                continue;
            };
            if *kind != Touch::Drop {
                return Err(failed(format!(
                    "{column} is an embedded column: it can't be changed, renamed or retyped; \
                     change its model or source with MODIFY COLUMN ... GENERATED BY EMBEDDING, \
                     or drop it"
                )));
            }
            let mut extra = vec![
                format!(
                    "DROP COLUMN IF EXISTS {}",
                    quote(&embedcol::src_column(&e.column, None))
                ),
                format!(
                    "DROP COLUMN IF EXISTS {}",
                    quote(&embedcol::hash_column(&e.column, None))
                ),
            ];
            if let Some(p) = &e.pending {
                extra.extend(embedcol::drop_shadow_specs(
                    &e.column,
                    p.generation,
                    p.new_source,
                ));
            }
            edits.push((
                span.clone(),
                format!("{}, {}", &sql[span.clone()], extra.join(", ")),
            ));
            dropped.push(e.clone());
        }
        if dropped.is_empty() {
            return Ok(false);
        }
        let rewritten = embedcol::splice(sql, edits);
        self.embed_run(cx, wire, &rewritten).await?;
        let (svc, tenant, _) = self.services_and_tenant()?;
        let ep = svc.locator.writer(tenant).await?;
        let mut conn = ep.pool.get_conn_bounded().await.map_err(|e| {
            SprigError::new(SprigCode::CatalogUnavailable, "catalog unreachable").with_source(e)
        })?;
        let store = Store::new(ep.store.schema());
        let subs = Subscriptions::new(svc.locator.dc_store());
        for e in dropped {
            store.delete(&mut conn, e.id).await?;
            match subs.drop_subscription(tenant, &sub_name(e.id)).await {
                Ok(()) => {}
                Err(x) if x.code() == Some(SprigCode::FeedSubscriptionNotFound) => {}
                Err(x) => return Err(x),
            }
            tracing::info!(%tenant, %db, %table, column = %e.column, embedding = e.id, "embedded column dropped");
        }
        Ok(true)
    }
}

/// `db`.`table`'s database and object ids in `cat`.
fn table_in(cat: &TenantCatalog, db: &str, table: &str, lctn: bool) -> Option<(u32, u64)> {
    let d = cat.database(&database_key(db, lctn))?;
    let o = cat
        .object(
            d.db_id,
            Namespace::Relation,
            &object_key(ObjectKind::Table, table, lctn),
        )
        .filter(|o| o.state == ObjectState::Active)?;
    Some((d.db_id.0, o.object_id.0))
}

/// Registers embedded column `id`'s feed subscription at the feed's
/// position now: the worker's job misses no change committed after the
/// declaration, and its backfill covers the rows before it.
#[allow(clippy::too_many_arguments)] // the column's identity
async fn register(
    svc: &Arc<TenantServices>,
    tenant: sprig_common::ids::TenantId,
    id: u64,
    db: &str,
    table: &str,
    object: u64,
    column: &str,
) -> Result<()> {
    let subs = Subscriptions::new(svc.locator.dc_store());
    let name = sub_name(id);
    let (clusters, placement, names) = crate::http::changes::feed(svc)?;
    let tail = TenantTail::start(
        tenant,
        StartAt::Now,
        clusters,
        Arc::clone(&placement),
        names,
        TailOptions {
            progress_every: Duration::from_millis(500),
            ..TailOptions::default()
        },
    )
    .await?;
    let segment = placement
        .history(tenant)
        .await?
        .last()
        .map_or(0, |h| h.map_version);
    let token = ResumeToken {
        tenant,
        clamp: 0,
        cluster: tail.cluster().clone(),
        segment,
        pos: tail.position().clone(),
        until: None,
        progress: true,
    };
    drop(tail);
    let now_ms = u64::try_from(
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| d.as_millis()),
    )
    .unwrap_or(0);
    let sub = Subscription {
        tenant,
        name,
        kind: KIND.to_owned(),
        ordering: "merged".to_owned(),
        owner_ref: Some(
            json!({"embedding": id, "db": db, "table": table, "object": object, "column": column})
                .to_string(),
        ),
        state: "active".to_owned(),
        created_at_ms: now_ms,
    };
    subs.register_at(&sub, &token, now_ms)
        .await
        .map_err(|e| SprigError::internal(format!("the embedded column's subscription: {e}")))
}
